public final class GridKey {
    private final int row;
    private final int column;
    public GridKey(int row, int column) { this.row = row; this.column = column; }
    public int row() { return row; }
    public int column() { return column; }
    @Override public boolean equals(Object other) {
        if (this == other) return true;
        if (!(other instanceof GridKey)) return false;
        GridKey key = (GridKey) other;
        return row == key.row && column == key.column;
    }
    @Override public int hashCode() { return 31 * row + column; }
}
